sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below

    if (g_form.isNewRecord()) {
		var movilBox = new GlideAjax("GetPhoneNumber"); //Nombre del ScriptInclude
		movilBox.addParam('sysparm_name', 'getCurrentPhone' ); //Nombre del método a usar

		/*movilBox.addParam('sysparm_UserID', g_form.getValue('u_requested_for'));*/ 

		//En el onChange() esta línea es obligatoria ya que necesitamos el parámetro del campo que el usuario modifica. En este caso onLoad() el formulario se carga y no necesitamos que el usuario toque nada.

		movilBox.getXMLAnswer(setPhone);
    }

	function setPhone(answer){
		g_form.setValue('u_requested_for_phone',answer);
	}
}
